CREATE SCHEMA IF NOT EXISTS business;
COMMENT ON SCHEMA business IS 'Verified business accounts, teams, branches, storefronts and lead analytics';

CREATE TABLE business.accounts(
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),owner_user_id uuid NOT NULL REFERENCES identity.users(id),slug citext NOT NULL,display_name varchar(120) NOT NULL,legal_name varchar(160) NOT NULL,national_id_hash char(64),logo_url text,cover_url text,description varchar(1000) NOT NULL DEFAULT '',website_url text,verification_state text NOT NULL DEFAULT 'unverified'CHECK(verification_state IN('unverified','pending','verified','rejected','expired')),verified_at timestamptz,state text NOT NULL DEFAULT 'active'CHECK(state IN('active','suspended','closed')),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),deleted_at timestamptz,CHECK(slug::text~'^[a-z0-9][a-z0-9-]{2,62}$'),CHECK(national_id_hash IS NULL OR national_id_hash~'^[a-f0-9]{64}$'),CHECK((verification_state='verified')=(verified_at IS NOT NULL)),UNIQUE(tenant_id,slug)
);
CREATE INDEX business_owner_idx ON business.accounts(tenant_id,owner_user_id,state)WHERE deleted_at IS NULL;

CREATE TABLE business.verification_requests(
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),business_id uuid NOT NULL REFERENCES business.accounts(id)ON DELETE RESTRICT,submitted_by uuid NOT NULL REFERENCES identity.users(id),kind text NOT NULL CHECK(kind IN('legal','trade','identity','address')),document_refs jsonb NOT NULL DEFAULT '[]'CHECK(jsonb_typeof(document_refs)='array'),state text NOT NULL DEFAULT 'pending'CHECK(state IN('pending','reviewing','approved','rejected','expired')),reviewer_id uuid,reason_code varchar(80),submitted_at timestamptz NOT NULL DEFAULT clock_timestamp(),decided_at timestamptz,updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK((state IN('approved','rejected'))=(decided_at IS NOT NULL))
);CREATE INDEX business_verification_queue_idx ON business.verification_requests(tenant_id,state,submitted_at)WHERE state IN('pending','reviewing');

CREATE TABLE business.memberships(
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),business_id uuid NOT NULL REFERENCES business.accounts(id)ON DELETE RESTRICT,user_id uuid NOT NULL REFERENCES identity.users(id)ON DELETE RESTRICT,role text NOT NULL CHECK(role IN('owner','admin','listing_manager','support','analyst','billing')),permissions jsonb NOT NULL DEFAULT '[]'CHECK(jsonb_typeof(permissions)='array'),state text NOT NULL DEFAULT 'active'CHECK(state IN('invited','active','suspended','revoked')),invited_by uuid REFERENCES identity.users(id),joined_at timestamptz,last_active_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(business_id,user_id)
);CREATE INDEX business_membership_user_idx ON business.memberships(tenant_id,user_id,state);CREATE UNIQUE INDEX business_single_owner_idx ON business.memberships(business_id)WHERE role='owner'AND state='active';
CREATE FUNCTION business.guard_owner_membership()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF OLD.role='owner'AND OLD.state='active'AND(NEW.role<>'owner'OR NEW.state<>'active')THEN RAISE EXCEPTION'business_owner_transfer_required';END IF;RETURN NEW;END$$;CREATE TRIGGER business_owner_guard BEFORE UPDATE ON business.memberships FOR EACH ROW EXECUTE FUNCTION business.guard_owner_membership();

CREATE TABLE business.invitations(
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),business_id uuid NOT NULL REFERENCES business.accounts(id)ON DELETE RESTRICT,destination_hash char(64) NOT NULL,role text NOT NULL CHECK(role IN('admin','listing_manager','support','analyst','billing')),permissions jsonb NOT NULL DEFAULT '[]'CHECK(jsonb_typeof(permissions)='array'),token_hash bytea NOT NULL,invited_by uuid NOT NULL REFERENCES identity.users(id),expires_at timestamptz NOT NULL,state text NOT NULL DEFAULT 'pending'CHECK(state IN('pending','accepted','revoked','expired')),accepted_by uuid REFERENCES identity.users(id),accepted_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(expires_at>created_at),CHECK((state='accepted')=(accepted_at IS NOT NULL)),UNIQUE(token_hash)
);CREATE UNIQUE INDEX business_pending_invitation_idx ON business.invitations(business_id,destination_hash)WHERE state='pending';CREATE INDEX business_invitation_expiry_idx ON business.invitations(tenant_id,state,expires_at)WHERE state='pending';

CREATE TABLE business.branches(
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),business_id uuid NOT NULL REFERENCES business.accounts(id)ON DELETE RESTRICT,city_id uuid REFERENCES geo.places(id),neighborhood_id uuid REFERENCES geo.places(id),title varchar(120) NOT NULL,slug citext NOT NULL,public_phone varchar(32),public_address varchar(500),location geography(Point,4326),working_hours jsonb NOT NULL DEFAULT '{}'CHECK(jsonb_typeof(working_hours)='object'),state text NOT NULL DEFAULT 'active'CHECK(state IN('active','inactive','closed')),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(business_id,slug)
);CREATE INDEX business_branch_location_idx ON business.branches USING gist(location)WHERE state='active';

CREATE TABLE business.storefronts(
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),business_id uuid NOT NULL REFERENCES business.accounts(id)ON DELETE RESTRICT,slug citext NOT NULL,headline varchar(160) NOT NULL DEFAULT '',description varchar(2000) NOT NULL DEFAULT '',theme jsonb NOT NULL DEFAULT '{}'CHECK(jsonb_typeof(theme)='object'),social_links jsonb NOT NULL DEFAULT '{}'CHECK(jsonb_typeof(social_links)='object'),seo jsonb NOT NULL DEFAULT '{}'CHECK(jsonb_typeof(seo)='object'),state text NOT NULL DEFAULT 'draft'CHECK(state IN('draft','published','paused','archived')),published_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(slug::text~'^[a-z0-9][a-z0-9-]{2,62}$'),UNIQUE(tenant_id,slug),UNIQUE(business_id)
);CREATE INDEX business_storefront_public_idx ON business.storefronts(tenant_id,slug)WHERE state='published';
CREATE FUNCTION business.guard_storefront_publish()RETURNS trigger LANGUAGE plpgsql AS $$DECLARE account_state text;BEGIN IF NEW.state='published'THEN SELECT verification_state INTO account_state FROM business.accounts WHERE id=NEW.business_id;IF account_state<>'verified'THEN RAISE EXCEPTION'business_verification_required';END IF;NEW.published_at=coalesce(NEW.published_at,clock_timestamp());END IF;RETURN NEW;END$$;CREATE TRIGGER business_storefront_publish BEFORE INSERT OR UPDATE ON business.storefronts FOR EACH ROW EXECUTE FUNCTION business.guard_storefront_publish();

ALTER TABLE listing.posts ADD COLUMN business_id uuid REFERENCES business.accounts(id),ADD COLUMN branch_id uuid REFERENCES business.branches(id),ADD COLUMN assigned_member_id uuid REFERENCES business.memberships(id);
CREATE INDEX listing_posts_business_idx ON listing.posts(tenant_id,business_id,status,created_at DESC)WHERE business_id IS NOT NULL;
CREATE TABLE business.listing_assignments(
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),business_id uuid NOT NULL REFERENCES business.accounts(id),listing_id uuid NOT NULL REFERENCES listing.posts(id)ON DELETE CASCADE,member_id uuid NOT NULL REFERENCES business.memberships(id),assigned_by uuid NOT NULL REFERENCES identity.users(id),state text NOT NULL DEFAULT 'active'CHECK(state IN('active','completed','revoked')),assigned_at timestamptz NOT NULL DEFAULT clock_timestamp(),completed_at timestamptz,UNIQUE(listing_id,member_id)
);CREATE INDEX business_assignment_member_idx ON business.listing_assignments(tenant_id,member_id,state,assigned_at DESC);

CREATE TABLE business.lead_events(
  id uuid NOT NULL DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),business_id uuid NOT NULL REFERENCES business.accounts(id),listing_id uuid REFERENCES listing.posts(id),branch_id uuid REFERENCES business.branches(id),kind text NOT NULL CHECK(kind IN('view','contact','chat','call')),visitor_hash bytea NOT NULL,source varchar(64) NOT NULL DEFAULT 'direct',medium varchar(64) NOT NULL DEFAULT 'direct',campaign varchar(120) NOT NULL DEFAULT 'direct',referrer varchar(500),metadata jsonb NOT NULL DEFAULT '{}'CHECK(jsonb_typeof(metadata)='object'),occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(id,occurred_at)
)PARTITION BY RANGE(occurred_at);CREATE TABLE business.lead_events_default PARTITION OF business.lead_events DEFAULT;CREATE INDEX business_lead_events_lookup_idx ON business.lead_events(tenant_id,business_id,occurred_at DESC);CREATE INDEX business_lead_events_listing_idx ON business.lead_events(tenant_id,listing_id,occurred_at DESC)WHERE listing_id IS NOT NULL;

CREATE TABLE business.metric_snapshots(
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),business_id uuid NOT NULL REFERENCES business.accounts(id),branch_id uuid REFERENCES business.branches(id),bucket_date date NOT NULL,view_count bigint NOT NULL DEFAULT 0 CHECK(view_count>=0),contact_count bigint NOT NULL DEFAULT 0 CHECK(contact_count>=0),chat_count bigint NOT NULL DEFAULT 0 CHECK(chat_count>=0),call_count bigint NOT NULL DEFAULT 0 CHECK(call_count>=0),unique_visitor_count bigint NOT NULL DEFAULT 0 CHECK(unique_visitor_count>=0),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(business_id,bucket_date)
);CREATE INDEX business_metrics_range_idx ON business.metric_snapshots(tenant_id,business_id,bucket_date DESC);

CREATE TABLE business.activity_log(
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),business_id uuid NOT NULL REFERENCES business.accounts(id),actor_id uuid,action varchar(120) NOT NULL,resource_type varchar(80) NOT NULL,resource_id uuid,outcome text NOT NULL CHECK(outcome IN('success','denied','failure')),metadata jsonb NOT NULL DEFAULT '{}'CHECK(jsonb_typeof(metadata)='object'),occurred_at timestamptz NOT NULL DEFAULT clock_timestamp()
);CREATE INDEX business_activity_idx ON business.activity_log(tenant_id,business_id,occurred_at DESC);
CREATE FUNCTION business.reject_activity_mutation()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION'business_activity_append_only';END$$;CREATE TRIGGER business_activity_immutable BEFORE UPDATE OR DELETE ON business.activity_log FOR EACH ROW EXECUTE FUNCTION business.reject_activity_mutation();

ALTER TABLE monetization.orders ADD CONSTRAINT monetization_orders_business_fk FOREIGN KEY(business_id)REFERENCES business.accounts(id);
ALTER TABLE monetization.entitlements ADD CONSTRAINT monetization_entitlements_business_fk FOREIGN KEY(business_id)REFERENCES business.accounts(id);
ALTER TABLE monetization.subscriptions ADD CONSTRAINT monetization_subscriptions_business_fk FOREIGN KEY(business_id)REFERENCES business.accounts(id);

DO $$DECLARE table_name text;BEGIN FOREACH table_name IN ARRAY ARRAY['accounts','verification_requests','memberships','invitations','branches','storefronts','listing_assignments','lead_events','metric_snapshots','activity_log']LOOP EXECUTE format('ALTER TABLE business.%I ENABLE ROW LEVEL SECURITY',table_name);EXECUTE format('ALTER TABLE business.%I FORCE ROW LEVEL SECURITY',table_name);EXECUTE format('CREATE POLICY %I ON business.%I USING(tenant_id=NULLIF(current_setting(''app.current_tenant_id'',true),'''')::uuid)WITH CHECK(tenant_id=NULLIF(current_setting(''app.current_tenant_id'',true),'''')::uuid)',table_name||'_tenant_isolation',table_name);END LOOP;END$$;
